import{_ as a,o as t,c as r,al as i}from"./chunks/framework.7vp1BMOE.js";const m=JSON.parse('{"title":"Розумні акумулятори","description":"","frontmatter":{},"headers":[],"relativePath":"uk/smart_batteries/index.md","filePath":"uk/smart_batteries/index.md"}'),o={name:"uk/smart_batteries/index.md"};function l(s,e,n,_,d,f){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="розумні-акумулятори" tabindex="-1">Розумні акумулятори <a class="header-anchor" href="#розумні-акумулятори" aria-label="Permalink to &quot;Розумні акумулятори&quot;">​</a></h1><p>Розумні батареї надають більш точну (і часто більш детальну) інформацію про стан батареї, ніж автопілот може оцінити для «тупих» батарей. This allows for more reliable flight planning notification of failure conditions. Інформація може включати деякі з наступного: залишковий заряд, час до розряду (оцінений), напругу на елементах (оцінена максимальна/мінімальна, поточна напруга тощо), температуру, струми, інформацію про несправності, виробника батареї, хімічний склад тощо.</p><p>PX4 підтримує (принаймні) наступні розумні батарейки:</p><ul><li><a href="./../smart_batteries/rotoye_batmon">Rotoye Batmon</a> (Discontinued)</li></ul><h3 id="подальша-інформація" tabindex="-1">Подальша інформація <a class="header-anchor" href="#подальша-інформація" aria-label="Permalink to &quot;Подальша інформація&quot;">​</a></h3><ul><li><a href="https://mavlink.io/en/services/battery.html" target="_blank" rel="noreferrer">Mavlink Battery Protocol</a></li><li><a href="./../modules/modules_driver#batt-smbus">batt_smbus</a> - PX4 SMBus Battery Driver docs</li><li><a href="./../config/safety#battery-level-failsafe">Safety &gt; Low Battery Failsafe</a>.</li></ul>',6)])])}const u=a(o,[["render",l]]);export{m as __pageData,u as default};
